1	namespace Maxx.Domain.Catalogo;
2	
3	// Referencia é o código do item ou da família com problema.
4	public sealed record ErroDeCatalogo(string Referencia, string Mensagem)
5	{
6	    public override string ToString() => $"{Referencia}: {Mensagem}";
7	}
8	
9	// O catálogo é dado, e perde o que o compilador daria de graça (ADR 0004). Este
10	// validador é a compensação: roda na CI e antes de o seeder gravar qualquer coisa.
11	// Devolve todos os erros de uma vez, para uma correção não revelar a próxima.
12	public static class CatalogoValidator
13	{
14	    private static readonly HashSet<CampoDeDeduplicacao> _camposDeMedalha =
15	    [
16	        CampoDeDeduplicacao.Aluno, CampoDeDeduplicacao.Item, CampoDeDeduplicacao.Materia,
17	        CampoDeDeduplicacao.Bimestre, CampoDeDeduplicacao.Semestre, CampoDeDeduplicacao.Ocorrencia,
18	    ];
19	
20	    private static readonly HashSet<CampoDeDeduplicacao> _camposDePremioParticipacao =
21	    [
22	        CampoDeDeduplicacao.Aluno, CampoDeDeduplicacao.Item, CampoDeDeduplicacao.Evento,
23	        CampoDeDeduplicacao.DataDoEvento, CampoDeDeduplicacao.Materia,
24	    ];
25	
26	    public static IReadOnlyList<ErroDeCatalogo> Validar(Catalogo catalogo)
27	    {
28	        ArgumentNullException.ThrowIfNull(catalogo);
29	
30	        var erros = new List<ErroDeCatalogo>();
31	        var itensPorCodigo = new Dictionary<string, ItemCatalogo>(StringComparer.Ordinal);
32	
33	        foreach (var item in catalogo.Itens)
34	        {
35	            if (!itensPorCodigo.TryAdd(item.Codigo, item))
36	            {
37	                erros.Add(new(item.Codigo, "código repetido no catálogo."));
38	            }
39	        }
40	
41	        foreach (var item in catalogo.Itens)
42	        {
43	            ValidarComum(item, erros);
44	
45	            switch (item)
46	            {
47	                case ItemMedalha medalha:
48	                    ValidarMedalha(medalha, erros);
49	                    break;
50	                case ItemPremioParticipacao premio:
51	                    ValidarPremioParticipacao(premio, erros);
52	                    break;
53	                case ItemConquista conquista:
54	                    ValidarConquista(conquista, itensPorCodigo, erros);
55	                    break;
56	            }
57	        }
58	
59	        ValidarFamilias(catalogo, erros);
60	
61	        return erros;
62	    }
63	
64	    private static void ValidarComum(ItemCatalogo item, List<ErroDeCatalogo> erros)
65	    {
66	        var prefixo = item.Tipo switch
67	        {
68	            TipoDeItem.Medalha => 'M',
69	            TipoDeItem.PremioParticipacao => 'P',
70	            _ => 'C',
71	        };
72	
73	        if (item.Codigo.Length < 2 || item.Codigo[0] != prefixo || !item.Codigo[1..].All(char.IsAsciiDigit))
74	        {
75	            erros.Add(new(item.Codigo, $"código de {item.Tipo} precisa ser {prefixo} seguido de dígitos."));
76	        }
77	
78	        if (string.IsNullOrWhiteSpace(item.Nome))
79	        {
80	            erros.Add(new(item.Codigo, "nome vazio."));
81	        }
82	
83	        if (string.IsNullOrWhiteSpace(item.Descricao))
84	        {
85	            erros.Add(new(item.Codigo, "descrição vazia."));
86	        }
87	
88	        var faixa = Tiers.Faixa(item.Tier);
89	        if (!faixa.Contem(item.Pontos))
90	        {
91	            erros.Add(new(item.Codigo, $"{item.Pontos} pontos fora da faixa {item.Tier} ({faixa})."));
92	        }
93	
94	        if ((item.Familia is null) != (item.OrdemNaFamilia is null))
95	        {
96	            erros.Add(new(item.Codigo, "família e ordem na família vêm juntas, ou nenhuma das duas."));
97	        }
98	
99	        if (item.Vigencia is { Inicio: { } inicio, Fim: { } fim } && fim < inicio)
100	        {
101	            erros.Add(new(item.Codigo, "vigência termina antes de começar."));
102	        }
103	    }
104	
105	    private static void ValidarMedalha(ItemMedalha medalha, List<ErroDeCatalogo> erros)
106	    {
107	        if (medalha.PeriodoDeReferencia is not (Periodo.Bimestre or Periodo.Semestre))
108	        {
109	            erros.Add(new(medalha.Codigo, $"medalha é de bimestre ou de semestre, não de {medalha.PeriodoDeReferencia}."));
110	        }
111	
112	        // Fato isolado em Bronze; só as de fechamento de matéria (semestre) passam disso.
113	        if (medalha.Tier != Tier.Bronze && medalha.PeriodoDeReferencia != Periodo.Semestre)
114	        {
115	            erros.Add(new(medalha.Codigo, $"medalha {medalha.Tier} só existe como fechamento de matéria, no semestre."));
116	        }
117	
118	        var chave = medalha.ChaveDeDeduplicacao;
119	        ValidarChave(medalha.Codigo, chave, _camposDeMedalha, erros);
120	
121	        if (!chave.Contains(CampoDeDeduplicacao.Item) || !chave.Contains(CampoDeDeduplicacao.Materia))
122	        {
123	            erros.Add(new(medalha.Codigo, "a chave de deduplicação da medalha precisa de item e matéria."));
124	        }
125	
126	        var campoDoPeriodo = medalha.PeriodoDeReferencia == Periodo.Semestre
127	            ? CampoDeDeduplicacao.Semestre
128	            : CampoDeDeduplicacao.Bimestre;
129	        if (!chave.Contains(campoDoPeriodo))
130	        {
131	            erros.Add(new(medalha.Codigo, $"a chave de deduplicação precisa do período de referência ({campoDoPeriodo})."));
132	        }
133	
134	        // Nos itens repetíveis, a ocorrência entra na chave e é o que o limite controla.
135	        if (medalha.Repetivel != chave.Contains(CampoDeDeduplicacao.Ocorrencia))
136	        {
137	            erros.Add(new(medalha.Codigo, "ocorrência está na chave se, e só se, a medalha é repetível."));
138	        }
139	
140	        if (medalha.Repetivel && medalha.LimitePorPeriodo < 2)
141	        {
142	            erros.Add(new(medalha.Codigo, "medalha repetível precisa de limite por período de ao menos 2."));
143	        }
144	
145	        if (!medalha.Repetivel && medalha.LimitePorPeriodo != 1)
146	        {
147	            erros.Add(new(medalha.Codigo, "medalha não repetível tem limite por período 1."));
148	        }
149	    }
150	
151	    private static void ValidarPremioParticipacao(ItemPremioParticipacao premio, List<ErroDeCatalogo> erros)
152	    {
153	        if (premio.PeriodoDeReferencia != Periodo.Evento)
154	        {
155	            erros.Add(new(premio.Codigo, "prêmio de participação conta no semestre do evento: período de referência é evento."));
156	        }
157	
158	        if (string.IsNullOrWhiteSpace(premio.TipoDeEvento))
159	        {
160	            erros.Add(new(premio.Codigo, "tipo de evento vazio."));
161	        }
162	
163	        var chave = premio.ChaveDeDeduplicacao;
164	        ValidarChave(premio.Codigo, chave, _camposDePremioParticipacao, erros);
165	
166	        if (!chave.Contains(CampoDeDeduplicacao.Evento) && !chave.Contains(CampoDeDeduplicacao.DataDoEvento))
167	        {
168	            erros.Add(new(premio.Codigo, "a chave de deduplicação precisa do evento ou da data do evento."));
169	        }
170	    }
171	
172	    private static void ValidarChave(
173	        string codigo,
174	        IReadOnlyList<CampoDeDeduplicacao> chave,
175	        HashSet<CampoDeDeduplicacao> permitidos,
176	        List<ErroDeCatalogo> erros)
177	    {
178	        if (!chave.Contains(CampoDeDeduplicacao.Aluno))
179	        {
180	            erros.Add(new(codigo, "a chave de deduplicação precisa do aluno."));
181	        }
182	
183	        foreach (var campo in chave.Where(campo => !permitidos.Contains(campo)).Distinct())
184	        {
185	            erros.Add(new(codigo, $"{campo} não pertence à chave de deduplicação deste tipo."));
186	        }
187	
188	        if (chave.Distinct().Count() != chave.Count)
189	        {
190	            erros.Add(new(codigo, "campo repetido na chave de deduplicação."));
191	        }
192	    }
193	
194	    private static void ValidarConquista(
195	        ItemConquista conquista, Dictionary<string, ItemCatalogo> itensPorCodigo, List<ErroDeCatalogo> erros)
196	    {
197	        var codigo = conquista.Codigo;
198	        var regra = conquista.Regra;
199	
200	        if (conquista.Periodo == Periodo.Evento)
201	        {
202	            erros.Add(new(codigo, "conquista é de bimestre, semestre, ano ou curso, não de evento."));
203	        }
204	
205	        // A instância do período curso é o próprio aluno, sem fronteira de data: nunca fecha.
206	        if (conquista.Periodo == Periodo.Curso && conquista.Gatilho == Gatilho.FechamentoDePeriodo)
207	        {
208	            erros.Add(new(codigo, "período curso não tem fechamento: o gatilho é porFato."));
209	        }
210	
211	        if (regra.Forma == FormaDeContagem.Customizada)
212	        {
213	            if (string.IsNullOrWhiteSpace(regra.Implementacao))
214	            {
215	                erros.Add(new(codigo, "regra customizada precisa do nome da implementação."));
216	            }
217	
218	            return;
219	        }
220	
221	        if (regra.Implementacao is not null)
222	        {
223	            erros.Add(new(codigo, "implementação só existe na regra customizada."));
224	        }
225	
226	        if (regra.Fonte is not { } fonte)
227	        {
228	            erros.Add(new(codigo, "regra sem fonte."));
229	            return;
230	        }
231	
232	        // O prêmio de participação conta no semestre do evento e não tem bimestre
233	        // (produto.md 4.9): numa instância de bimestre, ele nunca entraria na contagem.
234	        if (conquista.Periodo == Periodo.Bimestre && fonte != FonteDeContagem.Medalha)
235	        {
236	            erros.Add(new(codigo, "prêmio de participação conta no semestre do evento: conquista de bimestre só conta medalha."));
237	        }
238	
239	        ValidarFiltro(codigo, fonte, regra.FiltroItens, itensPorCodigo, erros);
240	        ValidarAgrupamento(codigo, regra, fonte, erros);
241	        ValidarAlvo(conquista, erros);
242	    }
243	
244	    private static void ValidarFiltro(
245	        string codigo,
246	        FonteDeContagem fonte,
247	        IReadOnlyList<string>? filtro,
248	        Dictionary<string, ItemCatalogo> itensPorCodigo,
249	        List<ErroDeCatalogo> erros)
250	    {
251	        if (filtro is null)
252	        {
253	            return;
254	        }
255	
256	        if (filtro.Count == 0)
257	        {
258	            erros.Add(new(codigo, "filtroItens vazio: use nulo para qualquer item da fonte."));
259	        }
260	
261	        foreach (var filtrado in filtro)
262	        {
263	            if (!itensPorCodigo.TryGetValue(filtrado, out var item))
264	            {
265	                erros.Add(new(codigo, $"filtroItens aponta para {filtrado}, que não existe."));
266	                continue;
267	            }
268	
269	            if (item.Tipo == TipoDeItem.Conquista)
270	            {
271	                erros.Add(new(codigo, $"filtroItens aponta para a conquista {filtrado}: conquista nunca conta outra conquista."));
272	                continue;
273	            }
274	
275	            var cabeNaFonte = fonte switch
276	            {
277	                FonteDeContagem.Medalha => item.Tipo == TipoDeItem.Medalha,
278	                FonteDeContagem.PremioParticipacao => item.Tipo == TipoDeItem.PremioParticipacao,
279	                _ => true,
280	            };
281	            if (!cabeNaFonte)
282	            {
283	                erros.Add(new(codigo, $"filtroItens aponta para {filtrado}, que não é da fonte {fonte}."));
284	            }
285	        }
286	    }
287	
288	    private static void ValidarAgrupamento(
289	        string codigo, RegraDeConquista regra, FonteDeContagem fonte, List<ErroDeCatalogo> erros)
290	    {
291	        switch (regra.Forma, regra.AgruparPor)
292	        {
293	            case (FormaDeContagem.Contagem, not null):
294	                erros.Add(new(codigo, "contagem simples não agrupa: agruparPor precisa ser nulo."));
295	                return;
296	            case (FormaDeContagem.ContagemDistinta, null):
297	                erros.Add(new(codigo, "contagem distinta precisa de agruparPor."));
298	                return;
299	            case (_, null):
300	                return;
301	        }
302	
303	        var fonteDoCampo = regra.AgruparPor == Agrupamento.TipoDeEvento
304	            ? FonteDeContagem.PremioParticipacao
305	            : FonteDeContagem.Medalha;
306	        if (fonte != fonteDoCampo)
307	        {
308	            erros.Add(new(codigo, $"agruparPor {regra.AgruparPor} só existe na fonte {fonteDoCampo}."));
309	        }
310	    }
311	
312	    private static void ValidarAlvo(ItemConquista conquista, List<ErroDeCatalogo> erros)
313	    {
314	        var codigo = conquista.Codigo;
315	
316	        switch (conquista.Regra.Alvo)
317	        {
318	            case null:
319	                erros.Add(new(codigo, "regra sem alvo."));
320	                break;
321	            case { Fixo: { } fixo } when fixo < 1:
322	                erros.Add(new(codigo, $"alvo {fixo}: precisa ser ao menos 1."));
323	                break;
324	            case { EhTodasAsMatriculasDoPeriodo: true }:
325	                if (conquista.Regra.AgruparPor != Agrupamento.Materia)
326	                {
327	                    erros.Add(new(codigo, "alvo todasAsMatriculasDoPeriodo só faz sentido agrupando por matéria."));
328	                }
329	
330	                // O alvo só existe completo no fim do período.
331	                if (conquista.Gatilho != Gatilho.FechamentoDePeriodo)
332	                {
333	                    erros.Add(new(codigo, "alvo todasAsMatriculasDoPeriodo exige gatilho fechamentoDePeriodo."));
334	                }
335	
336	                break;
337	        }
338	    }
