1	using Maxx.Domain.Academico;
2	using Maxx.Domain.Catalogo;
3	using Maxx.Domain.Identidade;
4	
5	namespace Maxx.Domain.Premios;
6	
7	// Concessão humana do professor, sobre fato de nota ou presença (produto.md 4.8). Grava
8	// turma e matéria de quem concede e o bimestre da data; congela tier, pontos e versão do
9	// item (ADR 0007). Não é contestável nem revogável: a instituição pode anular, e a medalha
10	// anulada deixa de pontuar e libera a vaga no limite do período.
11	public sealed class Medalha
12	{
13	    // Para o EF Core materializar do banco.
14	    private Medalha()
15	    {
16	        ItemCodigo = null!;
17	        ChaveDeDeduplicacao = null!;
18	    }
19	
20	    private Medalha(
21	        ItemMedalha item,
22	        int versaoDoItem,
23	        Usuario aluno,
24	        Turma turma,
25	        SemestreLetivo semestre,
26	        Bimestre bimestre,
27	        int ocorrencia,
28	        string chaveDeDeduplicacao,
29	        Usuario professor,
30	        DateTimeOffset agora)
31	    {
32	        Id = Guid.CreateVersion7();
33	        AlunoId = aluno.Id;
34	        ItemCodigo = item.Codigo;
35	        VersaoDoItem = versaoDoItem;
36	        Tier = item.Tier;
37	        Pontos = item.Pontos;
38	        TurmaId = turma.Id;
39	        MateriaId = turma.MateriaId;
40	        SemestreLetivoId = semestre.Id;
41	        BimestreId = bimestre.Id;
42	        Ocorrencia = ocorrencia;
43	        ChaveDeDeduplicacao = chaveDeDeduplicacao;
44	        ConcedidaPorId = professor.Id;
45	        ConcedidaEm = agora;
46	    }
47	
48	    public Guid Id { get; private set; }
49	
50	    // O usuário do aluno: só aluno com conta recebe medalha.
51	    public Guid AlunoId { get; private set; }
52	
53	    public string ItemCodigo { get; private set; }
54	
55	    public int VersaoDoItem { get; private set; }
56	
57	    public Tier Tier { get; private set; }
58	
59	    public int Pontos { get; private set; }
60	
61	    public Guid TurmaId { get; private set; }
62	
63	    public Guid MateriaId { get; private set; }
64	
65	    public Guid SemestreLetivoId { get; private set; }
66	
67	    // O bimestre da data da concessão, também nos itens de período semestre.
68	    public Guid BimestreId { get; private set; }
69	
70	    // Qual das vagas do limite por período esta medalha ocupa, de 1 ao limite.
71	    public int Ocorrencia { get; private set; }
72	
73	    // Os campos que o item declara em chaveDeDeduplicacao, com os valores desta concessão.
74	    // Única entre as medalhas ativas: é o que decide a corrida de duas concessões.
75	    public string ChaveDeDeduplicacao { get; private set; }
76	
77	    public Guid ConcedidaPorId { get; private set; }
78	
79	    public DateTimeOffset ConcedidaEm { get; private set; }
80	
81	    public Guid? AnuladaPorId { get; private set; }
82	
83	    public DateTimeOffset? AnuladaEm { get; private set; }
84	
85	    public bool EstaAtiva => AnuladaEm is null;
86	
87	    // existentes: as medalhas do aluno nesse item que quem chama carregou, ativas ou não;
88	    // as de outro período ou matéria são ignoradas aqui. siglaDoCurso é o curso atual do
89	    // aluno, para item restrito a curso.
90	    public static ResultadoDaConcessao Conceder(
91	        ItemMedalha item,
92	        int versaoDoItem,
93	        Usuario aluno,
94	        string siglaDoCurso,
95	        Turma turma,
96	        SemestreLetivo semestreDaTurma,
97	        Usuario professor,
98	        IEnumerable<Medalha> existentes,
99	        DateTimeOffset agora)
100	    {
101	        ArgumentNullException.ThrowIfNull(item);
102	        ArgumentNullException.ThrowIfNull(aluno);
103	        ArgumentNullException.ThrowIfNull(turma);
104	        ArgumentNullException.ThrowIfNull(semestreDaTurma);
105	        ArgumentNullException.ThrowIfNull(professor);
106	        ArgumentNullException.ThrowIfNull(existentes);
107	
108	        if (semestreDaTurma.Id != turma.SemestreLetivoId)
109	        {
110	            throw new ArgumentException("O semestre não é o da turma.", nameof(semestreDaTurma));
111	        }
112	
113	        var anteriores = existentes.ToList();
114	        if (anteriores.Any(medalha => medalha.AlunoId != aluno.Id || medalha.ItemCodigo != item.Codigo))
115	        {
116	            throw new ArgumentException("Há medalha de outro aluno ou de outro item.", nameof(existentes));
117	        }
118	
119	        if (!professor.Papeis.HasFlag(Papeis.Professor))
120	        {
121	            throw new DomainException($"Só professor concede medalha; {professor.Id} é {professor.Papeis}.");
122	        }
123	
124	        if (aluno.Papeis != Papeis.Aluno)
125	        {
126	            throw new DomainException($"Só aluno recebe medalha; {aluno.Id} é {aluno.Papeis}.");
127	        }
128	
129	        if (aluno.EhExAluno)
130	        {
131	            return ResultadoDaConcessao.Recusada(RecusaDaConcessao.ExAluno);
132	        }
133	
134	        var data = FusoHorario.DataLocal(agora);
135	        if (!semestreDaTurma.Contem(data))
136	        {
137	            return ResultadoDaConcessao.Recusada(RecusaDaConcessao.ForaDoSemestreDaTurma);
138	        }
139	
140	        var bimestre = semestreDaTurma.Bimestres.FirstOrDefault(candidato => candidato.Contem(data));
141	        if (bimestre is null)
142	        {
143	            return ResultadoDaConcessao.Recusada(RecusaDaConcessao.ForaDeBimestre);
144	        }
145	
146	        if (item.Vigencia is { Inicio: { } inicio } && data < inicio || item.Vigencia is { Fim: { } fim } && data > fim)
147	        {
148	            return ResultadoDaConcessao.Recusada(RecusaDaConcessao.ItemForaDeVigencia);
149	        }
150	
151	        if (item.RestricaoCurso is { } restricao && !string.Equals(restricao, siglaDoCurso, StringComparison.OrdinalIgnoreCase))
152	        {
153	            return ResultadoDaConcessao.Recusada(RecusaDaConcessao.ItemDeOutroCurso);
154	        }
155	
156	        // As vagas do período: mesma matéria e mesma instância do período de referência.
157	        var periodo = item.PeriodoDeReferencia switch
158	        {
159	            Periodo.Bimestre => bimestre.Id,
160	            Periodo.Semestre => semestreDaTurma.Id,
161	            _ => throw new DomainException($"Medalha {item.Codigo} com período {item.PeriodoDeReferencia}: só bimestre ou semestre."),
162	        };
163	        var ocupadas = anteriores
164	            .Where(medalha => medalha.EstaAtiva && medalha.MateriaId == turma.MateriaId)
165	            .Where(medalha => (item.PeriodoDeReferencia == Periodo.Bimestre ? medalha.BimestreId : medalha.SemestreLetivoId) == periodo)
166	            .Select(medalha => medalha.Ocorrencia)
167	            .ToHashSet();
168	        var ocorrencia = Enumerable.Range(1, item.LimitePorPeriodo).FirstOrDefault(vaga => !ocupadas.Contains(vaga));
169	        if (ocorrencia == 0)
170	        {
171	            return ResultadoDaConcessao.Recusada(RecusaDaConcessao.LimiteAtingido);
172	        }
173	
174	        var chave = Chave(item, aluno, turma, semestreDaTurma, bimestre, ocorrencia);
175	        return new ResultadoDaConcessao(
176	            new Medalha(item, versaoDoItem, aluno, turma, semestreDaTurma, bimestre, ocorrencia, chave, professor, agora),
177	            null);
178	    }
179	
180	    // Ato administrativo da instituição: sem motivo público e sem averiguação. false: já
181	    // estava anulada, e nada muda.
182	    public bool Anular(Guid instituicaoId, DateTimeOffset agora)
183	    {
184	        if (!EstaAtiva)
185	        {
186	            return false;
187	        }
188	
189	        AnuladaPorId = instituicaoId;
190	        AnuladaEm = agora;
191	        return true;
192	    }
