202	            CampoDeDeduplicacao.Semestre => $"semestre:{semestre.Id}",
203	            CampoDeDeduplicacao.Ocorrencia => $"ocorrencia:{ocorrencia}",
204	            _ => throw new DomainException($"Medalha {item.Codigo} não deduplica por {campo}."),
205	        }));
