using Maxx.Domain.Academico;
using Maxx.Domain.Conquistas;
using Maxx.Domain.Fotos;
using Maxx.Domain.Identidade;
using Maxx.Domain.Premios;

namespace Maxx.Domain.Social;

// O post do feed (produto.md 6.1): ao menos um entre prêmio, foto e legenda. Um prêmio
// rende um post. Só aluno ativo publica; o ex-aluno mantém os que já tinha. A foto são as
// duas derivadas de um upload confirmado na publicação (ADR 0002 e 0003).
//
// O prêmio é a medalha (passo 7), o prêmio de participação reivindicado (passo 8) ou a
// conquista (passo 9). Nunca mais de um por post.
public sealed class Post
{
    // Em caracteres, contando um emoji como um, como no nome de exibição.
    public const int TamanhoMaximoDaLegenda = 1000;

    // Para o EF Core materializar do banco.
    private Post()
    {
    }

    private Post(
        Guid autorId,
        string? legenda,
        UploadPendente? upload,
        Medalha? medalha,
        PremioParticipacao? premio,
        Conquista? conquista,
        DateTimeOffset agora)
    {
        Id = Guid.CreateVersion7();
        AutorId = autorId;
        Legenda = legenda;
        ChaveDaFotoDoFeed = upload?.ChaveDoFeed;
        ChaveDaFotoDaGrade = upload?.ChaveDaGrade;
        MedalhaId = medalha?.Id;
        PremioParticipacaoId = premio?.Id;
        ConquistaId = conquista?.Id;
        CriadoEm = agora;
    }

    public Guid Id { get; private set; }

    public Guid AutorId { get; private set; }

    public string? Legenda { get; private set; }

    public string? ChaveDaFotoDoFeed { get; private set; }

    public string? ChaveDaFotoDaGrade { get; private set; }

    public Guid? MedalhaId { get; private set; }

    // O prêmio de participação do post de reivindicação (passo 8). Nunca junto da medalha.
    public Guid? PremioParticipacaoId { get; private set; }

    // A conquista que o aluno postou (passo 9). Nunca junto de outro prêmio.
    public Guid? ConquistaId { get; private set; }

    public DateTimeOffset CriadoEm { get; private set; }

    // Remoção pela instituição (produto.md 2.1): o post some para todos, e fica quem
    // removeu e quando. O autor que apaga o próprio post o apaga de verdade.
    public DateTimeOffset? RemovidoEm { get; private set; }

    public Guid? RemovidoPorId { get; private set; }

    public bool TemFoto => ChaveDaFotoDoFeed is not null;

    public bool TemLegenda => Legenda is not null;

    public bool TemPremio => MedalhaId is not null || PremioParticipacaoId is not null || ConquistaId is not null;

    public bool EstaRemovido => RemovidoEm is not null;

    public IReadOnlyList<string> ChavesDaFoto => TemFoto ? [ChaveDaFotoDoFeed!, ChaveDaFotoDaGrade!] : [];

    public static ResultadoDaPublicacao Publicar(
        Usuario autor, string? legenda, UploadPendente? upload, Medalha? medalha, DateTimeOffset agora) =>
        Publicar(autor, legenda, upload, medalha, null, agora);

    // O upload e o prêmio chegam já buscados; se o prêmio já tem post é pergunta ao banco,
    // feita antes por quem chama e garantida pelo índice único. Publicado, o upload fica
    // confirmado e sai do alcance da limpeza. O prêmio é a medalha ou a conquista, nunca os
    // dois.
    public static ResultadoDaPublicacao Publicar(
        Usuario autor, string? legenda, UploadPendente? upload, Medalha? medalha, Conquista? conquista, DateTimeOffset agora) =>
        Publicar(autor, legenda, upload, medalha, conquista, null, agora);

    // O prêmio de participação entra aqui só pela concessão direta da instituição (passo 12,
    // P2), que não tem post de reivindicação: o aluno o posta como posta a medalha. Só o que
    // pontua (válido ou definitivo); o reivindicado já tem o post dele, e o índice único
    // garante um post por prêmio.
    public static ResultadoDaPublicacao Publicar(
        Usuario autor,
        string? legenda,
        UploadPendente? upload,
        Medalha? medalha,
        Conquista? conquista,
        PremioParticipacao? premioParticipacao,
        DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(autor);

        if (Conferir(autor, ref legenda, upload) is { } recusa)
        {
            return Recusa(recusa);
        }

        if (new object?[] { medalha, conquista, premioParticipacao }.Count(premio => premio is not null) > 1)
        {
            return Recusa(RecusaDaPublicacao.MaisDeUmPremio);
        }

        if (conquista is not null)
        {
            if (conquista.AlunoId != autor.Id)
            {
                return Recusa(RecusaDaPublicacao.PremioNaoEncontrado);
            }

            if (!conquista.EstaAtiva)
            {
                return Recusa(RecusaDaPublicacao.ConquistaRemovida);
            }
        }

        if (premioParticipacao is not null)
        {
            if (premioParticipacao.AlunoId != autor.Id)
            {
                return Recusa(RecusaDaPublicacao.PremioNaoEncontrado);
            }

            if (!premioParticipacao.Pontua)
            {
                return Recusa(RecusaDaPublicacao.PremioIndisponivel);
            }
        }

        if (medalha is not null)
        {
            if (medalha.AlunoId != autor.Id)
            {
                return Recusa(RecusaDaPublicacao.PremioNaoEncontrado);
            }

            if (!medalha.EstaAtiva)
            {
                return Recusa(RecusaDaPublicacao.PremioAnulado);
            }
        }

        if (legenda is null && upload is null && medalha is null && conquista is null && premioParticipacao is null)
        {
            return Recusa(RecusaDaPublicacao.Vazio);
        }

        upload?.Confirmar(agora);
        return new(new Post(autor.Id, legenda, upload, medalha, premioParticipacao, conquista, agora), null);
    }

    // O post de reivindicação (produto.md 4.7): a foto é obrigatória, porque é a
    // comprovação, e o prêmio acabou de ser reivindicado pelo próprio autor. Cada
    // reivindicação tem um post e uma foto só.
    public static ResultadoDaPublicacao Reivindicar(
        Usuario autor, string? legenda, UploadPendente? upload, PremioParticipacao premio, DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(autor);
        ArgumentNullException.ThrowIfNull(premio);

        if (premio.Estado != EstadoDoPremioParticipacao.Reivindicado)
        {
            throw new DomainException($"O post de reivindicação nasce com o prêmio; o {premio.Id} está {premio.Estado}.");
        }

        if (Conferir(autor, ref legenda, upload) is { } recusa)
        {
            return Recusa(recusa);
        }

        if (premio.AlunoId != autor.Id)
        {
            return Recusa(RecusaDaPublicacao.PremioNaoEncontrado);
        }

        if (upload is null)
        {
            return Recusa(RecusaDaPublicacao.FotoObrigatoria);
        }

        upload.Confirmar(agora);
        return new(new Post(autor.Id, legenda, upload, null, premio, null, agora), null);
    }

    // O que vale para todo post: só aluno ativo publica, a legenda cabe, e o upload é do
    // autor, de post e ainda não usado. A legenda volta aparada, ou nula se vazia.
    private static RecusaDaPublicacao? Conferir(Usuario autor, ref string? legenda, UploadPendente? upload)
    {
        if (autor.Papeis != Papeis.Aluno || autor.EhExAluno)
        {
            return RecusaDaPublicacao.AutorNaoPublica;
        }

        legenda = string.IsNullOrWhiteSpace(legenda) ? null : legenda.Trim();
        if (legenda is not null && legenda.EnumerateRunes().Count() > TamanhoMaximoDaLegenda)
        {
            return RecusaDaPublicacao.LegendaLonga;
        }

        if (upload is not null)
        {
            if (upload.UsuarioId != autor.Id || upload.Finalidade != FinalidadeDoUpload.Post)
            {
                return RecusaDaPublicacao.UploadNaoEncontrado;
            }

            if (upload.EstaConfirmado)
            {
                return RecusaDaPublicacao.UploadJaUsado;
            }
        }

        return null;
    }

    // Quem pede a remoção decide o modo: o autor apaga, a instituição remove. Ninguém mais,
    // nem o professor; post já removido não volta a ser removido.
    public ModoDeRemocao ModoDeRemocaoPor(Usuario quem)
    {
        ArgumentNullException.ThrowIfNull(quem);

        if (EstaRemovido)
        {
            return ModoDeRemocao.NaoPermitida;
        }

        if (quem.Id == AutorId)
        {
            return ModoDeRemocao.Apagar;
        }

        return quem.Papeis.HasFlag(Papeis.Instituicao) ? ModoDeRemocao.RemoverPelaInstituicao : ModoDeRemocao.NaoPermitida;
    }

    public void RemoverPelaInstituicao(Usuario instituicao, DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(instituicao);
        if (ModoDeRemocaoPor(instituicao) != ModoDeRemocao.RemoverPelaInstituicao)
        {
            throw new DomainException($"@{instituicao.Prefixo} não remove o post {Id} como instituição.");
        }

        RemovidoEm = agora;
        RemovidoPorId = instituicao.Id;
    }

    // Medalha anulada (decisão do passo 7, produto.md 4.8), e conquista removida pelo
    // recálculo (passo 9), do mesmo jeito: o post perde o vínculo e fica como post comum. Sem
    // foto nem legenda ele ficaria vazio, e post vazio não existe: quem chama o apaga em vez de
    // desvincular.
    public bool FicariaVazioSemPremio => !TemFoto && !TemLegenda;

    public void DesvincularPremio()
    {
        if (FicariaVazioSemPremio)
        {
            throw new DomainException($"O post {Id} ficaria vazio sem o prêmio: apague em vez de desvincular.");
        }

        MedalhaId = null;
        PremioParticipacaoId = null;
        ConquistaId = null;
    }

    private static ResultadoDaPublicacao Recusa(RecusaDaPublicacao recusa) => new(null, recusa);
}

public enum RecusaDaPublicacao
{
    AutorNaoPublica,
    LegendaLonga,
    Vazio,

    // Não existe, é de outra pessoa ou é de outra finalidade: para quem pede, dá no mesmo.
    UploadNaoEncontrado,
    UploadJaUsado,
    PremioNaoEncontrado,
    PremioAnulado,

    // A reivindicação sem foto: a foto é a comprovação.
    FotoObrigatoria,

    // A conquista que o recálculo removeu depois de uma anulação (passo 9).
    ConquistaRemovida,

    // Medalha e conquista no mesmo post: um prêmio por post.
    MaisDeUmPremio,

    // O prêmio de participação que não pontua agora: em averiguação, revogado ou ainda
    // reivindicado (passo 12).
    PremioIndisponivel,
}

public enum ModoDeRemocao
{
    NaoPermitida,
    Apagar,
    RemoverPelaInstituicao,
}

public sealed record ResultadoDaPublicacao(Post? Post, RecusaDaPublicacao? Recusa);

using System.ComponentModel.DataAnnotations;
using System.Security.Claims;
using Maxx.Api.Autenticacao;
using Maxx.Api.Medalhas;
using Maxx.Api.Premios;
using Maxx.Application;
using Maxx.Application.Fotos;
using Maxx.Application.Posts;
using Microsoft.AspNetCore.Http.HttpResults;

namespace Maxx.Api.Posts;

// O post (produto.md 6.1): publicar, ler e remover. A leitura é de qualquer usuário logado;
// é ela que o deep link /post/:id abre.
internal static class PostEndpoints
{
    public static IEndpointRouteBuilder MapPostEndpoints(this IEndpointRouteBuilder v1)
    {
        var posts = v1.MapGroup("/posts").WithTags("Posts");

        posts.MapPost("/", PublicarAsync)
            .WithName("PublicarPost")
            .ProducesValidationProblem()
            .ProducesProblem(StatusCodes.Status403Forbidden)
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict);

        posts.MapGet("/{postId:guid}", LerAsync)
            .WithName("GetPost")
            .ProducesProblem(StatusCodes.Status404NotFound);

        posts.MapDelete("/{postId:guid}", RemoverAsync)
            .WithName("RemoverPost")
            .ProducesProblem(StatusCodes.Status403Forbidden)
            .ProducesProblem(StatusCodes.Status404NotFound)
            .ProducesProblem(StatusCodes.Status409Conflict);

        return v1;
    }

    private static async Task<Created<PostResponse>> PublicarAsync(
        PublicarPostRequest pedido,
        ClaimsPrincipal principal,
        PublicarPostHandler handler,
        IConsultaDePosts consulta,
        IArmazenamentoDeFotos armazenamento,
        CancellationToken cancellationToken)
    {
        var post = await handler.PublicarAsync(
            UsuarioId(principal),
            pedido.Legenda,
            pedido.UploadId,
            pedido.MedalhaId,
            pedido.ConquistaId,
            pedido.PremioParticipacaoId,
            cancellationToken);
        var lido = await consulta.PostAsync(post.Id, UsuarioId(principal), cancellationToken)
            ?? throw new InvalidOperationException($"O post {post.Id} acabou de ser gravado e não foi lido.");
        return TypedResults.Created($"/api/v1/posts/{post.Id}", PostResponse.De(lido, armazenamento));
    }

    private static async Task<Ok<PostResponse>> LerAsync(
        Guid postId,
        ClaimsPrincipal principal,
        IConsultaDePosts consulta,
        IArmazenamentoDeFotos armazenamento,
        CancellationToken cancellationToken)
    {
        var lido = await consulta.PostAsync(postId, UsuarioId(principal), cancellationToken)
            ?? throw new RecusaException(TipoDeRecusa.NaoEncontrado, CodigosDoPost.PostNaoEncontrado, $"Post {postId} não existe.");
        return TypedResults.Ok(PostResponse.De(lido, armazenamento));
    }

    private static async Task<NoContent> RemoverAsync(
        Guid postId, ClaimsPrincipal principal, RemoverPostHandler handler, CancellationToken cancellationToken)
    {
        await handler.RemoverAsync(UsuarioId(principal), postId, cancellationToken);
        return TypedResults.NoContent();
    }

    // O sub do token; o grupo /v1 já exigiu um usuário autenticado.
    internal static Guid UsuarioId(ClaimsPrincipal principal) =>
        Guid.TryParse(principal.FindFirstValue(MaxxClaims.Sub), out var id)
            ? id
            : throw new InvalidOperationException("Token autenticado sem sub.");
}

// Ao menos um dos três; quem decide é o domínio. O limite da legenda é em caracteres,
// contando um emoji como um, e também do domínio: aqui só um teto bruto para o corpo.
// Um prêmio só: a medalha, a conquista (passo 9) ou o prêmio de participação concedido direto
// pela instituição (passo 12). Os dois últimos entraram como acréscimo.
public sealed record PublicarPostRequest(
    [property: StringLength(4000)] string? Legenda, Guid? UploadId, Guid? MedalhaId, Guid? ConquistaId = null, Guid? PremioParticipacaoId = null);

public sealed record PostResponse(
    Guid Id,
    AutorDoPostResponse Autor,
    string? Legenda,
    FotoDoPostResponse? Foto,
    PremioDoPostResponse? Premio,
    DateTimeOffset CriadoEm,
    int Curtidas,
    int Comentarios,
    bool Curtiu)
{
    public static PostResponse De(PostLido post, IArmazenamentoDeFotos armazenamento) => new(
        post.Id,
        new AutorDoPostResponse(
            post.Autor.Id,
            post.Autor.NomeDeExibicao,
            post.Autor.Arroba,
            post.Autor.Curso,
            post.Autor.Semestre,
            Leitura(armazenamento, post.Autor.ChaveDaFoto),
            post.Autor.Posicao),
        post.Legenda,
        post is { ChaveDaFotoDoFeed: { } feed, ChaveDaFotoDaGrade: { } grade }
            ? new FotoDoPostResponse(armazenamento.UrlDeLeitura(feed).AbsoluteUri, armazenamento.UrlDeLeitura(grade).AbsoluteUri)
            : null,
        post.Premio is { } premio
            ? new PremioDoPostResponse(
                ProfessorEndpoints.Nome(premio.Tipo),
                premio.Id,
                premio.Item,
                premio.Nome,
                ProfessorEndpoints.Nome(premio.Tier),
                premio.Pontos,
                premio.Raridade is { } raridade ? new RaridadeResponse(ProfessorEndpoints.Nome(raridade.Nivel), raridade.Percentual) : null,
                premio.Materia,
                premio.Bimestre,
                premio.Estado is { } estado ? ProfessorEndpoints.Nome(estado) : null,
                premio.Evento)
            : null,
        post.CriadoEm,
        post.Curtidas,
        post.Comentarios,
        post.Curtiu);

    // A URL pública de uma chave, ou nada.
    public static string? Leitura(IArmazenamentoDeFotos armazenamento, string? chave) =>
        chave is null ? null : armazenamento.UrlDeLeitura(chave).AbsoluteUri;
}

// Curso pela sigla e semestre do aluno (1º ao 8º), como na linha do autor no feed. A foto é a
// derivada da grade, para o avatar; sem foto, o app desenha as iniciais. A posição é a do
// histórico geral, nula sem pontos e nas filas da comprovação e da contestação (passo 11).
public sealed record AutorDoPostResponse(
    Guid Id, string NomeDeExibicao, string Arroba, string? Curso, int? Semestre, string? Foto, int? Posicao = null);

// A derivada do feed (~1080²) e a da grade (~320²), lidas direto da CDN.
public sealed record FotoDoPostResponse(string Feed, string Grade);

// Tipo, tier e raridade em camelCase, como no catálogo ("medalha", "bronze", "raro").
// Matéria e bimestre na medalha; matéria também na apresentação em sala. Estado e evento só
// no prêmio de participação (passo 8): "reivindicado" é a marca de pendente.
public sealed record PremioDoPostResponse(
    string Tipo,
    Guid Id,
    string Item,
    string Nome,
    string Tier,
    int Pontos,
    RaridadeResponse? Raridade,
    string? Materia,
    int? Bimestre,
    string? Estado,
    string? Evento);

