80	
81	    public static ResultadoDaPublicacao Publicar(
82	        Usuario autor, string? legenda, UploadPendente? upload, Medalha? medalha, DateTimeOffset agora) =>
83	        Publicar(autor, legenda, upload, medalha, null, agora);
84	
85	    // O upload e o prêmio chegam já buscados; se o prêmio já tem post é pergunta ao banco,
86	    // feita antes por quem chama e garantida pelo índice único. Publicado, o upload fica
87	    // confirmado e sai do alcance da limpeza. O prêmio é a medalha ou a conquista, nunca os
88	    // dois.
89	    public static ResultadoDaPublicacao Publicar(
90	        Usuario autor, string? legenda, UploadPendente? upload, Medalha? medalha, Conquista? conquista, DateTimeOffset agora) =>
91	        Publicar(autor, legenda, upload, medalha, conquista, null, agora);
92	
93	    // O prêmio de participação entra aqui só pela concessão direta da instituição (passo 12,
94	    // P2), que não tem post de reivindicação: o aluno o posta como posta a medalha. Só o que
95	    // pontua (válido ou definitivo); o reivindicado já tem o post dele, e o índice único
96	    // garante um post por prêmio.
97	    public static ResultadoDaPublicacao Publicar(
98	        Usuario autor,
99	        string? legenda,
100	        UploadPendente? upload,
101	        Medalha? medalha,
102	        Conquista? conquista,
103	        PremioParticipacao? premioParticipacao,
104	        DateTimeOffset agora)
105	    {
106	        ArgumentNullException.ThrowIfNull(autor);
107	
108	        if (Conferir(autor, ref legenda, upload) is { } recusa)
109	        {
110	            return Recusa(recusa);
111	        }
112	
113	        if (new object?[] { medalha, conquista, premioParticipacao }.Count(premio => premio is not null) > 1)
114	        {
115	            return Recusa(RecusaDaPublicacao.MaisDeUmPremio);
116	        }
117	
118	        if (conquista is not null)
119	        {
120	            if (conquista.AlunoId != autor.Id)
121	            {
122	                return Recusa(RecusaDaPublicacao.PremioNaoEncontrado);
123	            }
124	
125	            if (!conquista.EstaAtiva)
126	            {
127	                return Recusa(RecusaDaPublicacao.ConquistaRemovida);
128	            }
129	        }
130	
131	        if (premioParticipacao is not null)
132	        {
133	            if (premioParticipacao.AlunoId != autor.Id)
134	            {
135	                return Recusa(RecusaDaPublicacao.PremioNaoEncontrado);
136	            }
137	
138	            if (!premioParticipacao.Pontua)
139	            {
140	                return Recusa(RecusaDaPublicacao.PremioIndisponivel);
141	            }
142	        }
143	
144	        if (medalha is not null)
145	        {
146	            if (medalha.AlunoId != autor.Id)
147	            {
148	                return Recusa(RecusaDaPublicacao.PremioNaoEncontrado);
149	            }
150	
151	            if (!medalha.EstaAtiva)
152	            {
153	                return Recusa(RecusaDaPublicacao.PremioAnulado);
154	            }
155	        }
156	
157	        if (legenda is null && upload is null && medalha is null && conquista is null && premioParticipacao is null)
158	        {
159	            return Recusa(RecusaDaPublicacao.Vazio);
160	        }
161	
162	        upload?.Confirmar(agora);
163	        return new(new Post(autor.Id, legenda, upload, medalha, premioParticipacao, conquista, agora), null);
164	    }
165	
166	    // O post de reivindicação (produto.md 4.7): a foto é obrigatória, porque é a
167	    // comprovação, e o prêmio acabou de ser reivindicado pelo próprio autor. Cada
168	    // reivindicação tem um post e uma foto só.
169	    public static ResultadoDaPublicacao Reivindicar(
170	        Usuario autor, string? legenda, UploadPendente? upload, PremioParticipacao premio, DateTimeOffset agora)
171	    {
172	        ArgumentNullException.ThrowIfNull(autor);
173	        ArgumentNullException.ThrowIfNull(premio);
174	
175	        if (premio.Estado != EstadoDoPremioParticipacao.Reivindicado)
176	        {
177	            throw new DomainException($"O post de reivindicação nasce com o prêmio; o {premio.Id} está {premio.Estado}.");
178	        }
179	
180	        if (Conferir(autor, ref legenda, upload) is { } recusa)
181	        {
182	            return Recusa(recusa);
183	        }
184	
185	        if (premio.AlunoId != autor.Id)
186	        {
187	            return Recusa(RecusaDaPublicacao.PremioNaoEncontrado);
188	        }
189	
190	        if (upload is null)
191	        {
192	            return Recusa(RecusaDaPublicacao.FotoObrigatoria);
193	        }
194	
195	        upload.Confirmar(agora);
196	        return new(new Post(autor.Id, legenda, upload, null, premio, null, agora), null);
197	    }
198	
199	    // O que vale para todo post: só aluno ativo publica, a legenda cabe, e o upload é do
200	    // autor, de post e ainda não usado. A legenda volta aparada, ou nula se vazia.
201	    private static RecusaDaPublicacao? Conferir(Usuario autor, ref string? legenda, UploadPendente? upload)
202	    {
203	        if (autor.Papeis != Papeis.Aluno || autor.EhExAluno)
204	        {
205	            return RecusaDaPublicacao.AutorNaoPublica;
206	        }
207	
208	        legenda = string.IsNullOrWhiteSpace(legenda) ? null : legenda.Trim();
209	        if (legenda is not null && legenda.EnumerateRunes().Count() > TamanhoMaximoDaLegenda)
210	        {
211	            return RecusaDaPublicacao.LegendaLonga;
212	        }
213	
214	        if (upload is not null)
215	        {
216	            if (upload.UsuarioId != autor.Id || upload.Finalidade != FinalidadeDoUpload.Post)
217	            {
218	                return RecusaDaPublicacao.UploadNaoEncontrado;
219	            }
220	
221	            if (upload.EstaConfirmado)
222	            {
223	                return RecusaDaPublicacao.UploadJaUsado;
224	            }
225	        }
226	
227	        return null;
228	    }
229	
230	    // Quem pede a remoção decide o modo: o autor apaga, a instituição remove. Ninguém mais,
231	    // nem o professor; post já removido não volta a ser removido.
232	    public ModoDeRemocao ModoDeRemocaoPor(Usuario quem)
233	    {
234	        ArgumentNullException.ThrowIfNull(quem);
235	
236	        if (EstaRemovido)
237	        {
238	            return ModoDeRemocao.NaoPermitida;
239	        }
240	
241	        if (quem.Id == AutorId)
242	        {
243	            return ModoDeRemocao.Apagar;
244	        }
245	
246	        return quem.Papeis.HasFlag(Papeis.Instituicao) ? ModoDeRemocao.RemoverPelaInstituicao : ModoDeRemocao.NaoPermitida;
247	    }
248	
249	    public void RemoverPelaInstituicao(Usuario instituicao, DateTimeOffset agora)
250	    {
251	        ArgumentNullException.ThrowIfNull(instituicao);
252	        if (ModoDeRemocaoPor(instituicao) != ModoDeRemocao.RemoverPelaInstituicao)
253	        {
254	            throw new DomainException($"@{instituicao.Prefixo} não remove o post {Id} como instituição.");
255	        }
256	
257	        RemovidoEm = agora;
258	        RemovidoPorId = instituicao.Id;
259	    }
260	
261	    // Medalha anulada (decisão do passo 7, produto.md 4.8), e conquista removida pelo
262	    // recálculo (passo 9), do mesmo jeito: o post perde o vínculo e fica como post comum. Sem
263	    // foto nem legenda ele ficaria vazio, e post vazio não existe: quem chama o apaga em vez de
264	    // desvincular.
265	    public bool FicariaVazioSemPremio => !TemFoto && !TemLegenda;
266	
267	    public void DesvincularPremio()
268	    {
269	        if (FicariaVazioSemPremio)
270	        {
271	            throw new DomainException($"O post {Id} ficaria vazio sem o prêmio: apague em vez de desvincular.");
272	        }
273	
274	        MedalhaId = null;
275	        PremioParticipacaoId = null;
276	        ConquistaId = null;
277	    }
278	
279	    private static ResultadoDaPublicacao Recusa(RecusaDaPublicacao recusa) => new(null, recusa);
280	}
281	
282	public enum RecusaDaPublicacao
283	{
284	    AutorNaoPublica,
285	    LegendaLonga,
286	    Vazio,
287	
288	    // Não existe, é de outra pessoa ou é de outra finalidade: para quem pede, dá no mesmo.
289	    UploadNaoEncontrado,
290	    UploadJaUsado,
291	    PremioNaoEncontrado,
292	    PremioAnulado,
293	
294	    // A reivindicação sem foto: a foto é a comprovação.
295	    FotoObrigatoria,
296	
297	    // A conquista que o recálculo removeu depois de uma anulação (passo 9).
298	    ConquistaRemovida,
299	
300	    // Medalha e conquista no mesmo post: um prêmio por post.
301	    MaisDeUmPremio,
302	
303	    // O prêmio de participação que não pontua agora: em averiguação, revogado ou ainda
304	    // reivindicado (passo 12).
305	    PremioIndisponivel,
306	}
307	
308	public enum ModoDeRemocao
309	{
310	    NaoPermitida,
311	    Apagar,
312	    RemoverPelaInstituicao,
313	}
314	
315	public sealed record ResultadoDaPublicacao(Post? Post, RecusaDaPublicacao? Recusa);
