1	import type { components } from "@maxx/api-client";
2	
3	import { rotulosDeTier } from "../premios/rotulos";
4	import type { Raridade, Tier } from "../theme/tokens";
5	
6	export type PremiosDoAluno = components["schemas"]["PremiosDoAlunoResponse"];
7	export type ItemDoAluno = components["schemas"]["ItemDoAlunoResponse"];
8	export type Familia = components["schemas"]["FamiliaResponse"];
9	
10	// As duas abas da tela (prancheta trofeus-*.png). "Troféu" é rótulo só de interface: cobre
11	// prêmio de participação e conquista; medalha fica na outra aba (produto.md 4.1).
12	export type AbaDeTrofeus = "trofeus" | "medalhas";
13	
14	export const ehDaAba = (item: ItemDoAluno, aba: AbaDeTrofeus) =>
15	  aba === "medalhas" ? item.tipo === "medalha" : item.tipo !== "medalha";
16	
17	const obtido = (item: ItemDoAluno) => item.obtidos.length > 0;
18	
19	const pontosObtidos = (item: ItemDoAluno) =>
20	  item.obtidos.reduce((soma, premio) => soma + premio.pontos, 0);
21	
22	// Os itens da aba: os obtidos primeiro, depois os que faltam, cada grupo do maior valor
23	// para o menor. Sem "mostrar não obtidos", só os obtidos.
24	export function itensDaAba(
25	  itens: readonly ItemDoAluno[],
26	  aba: AbaDeTrofeus,
27	  mostrarNaoObtidos: boolean,
28	): ItemDoAluno[] {
29	  const daAba = itens.filter((item) => ehDaAba(item, aba));
30	  const porValor = (a: ItemDoAluno, b: ItemDoAluno) =>
31	    b.pontos - a.pontos || a.nome.localeCompare(b.nome, "pt-BR");
32	  const obtidos = daAba.filter(obtido).sort(porValor);
33	  return mostrarNaoObtidos
34	    ? [...obtidos, ...daAba.filter((item) => !obtido(item)).sort(porValor)]
35	    : obtidos;
36	}
37	
38	export interface PassoDaTrilha {
39	  id: string;
40	  rotulo: string;
41	  tier: Tier;
42	  glifo: "taca" | "fita";
43	  obtido: boolean;
44	  detalhes: string[];
45	}
46	
47	export interface Trilha {
48	  codigo: string;
49	  titulo: string;
50	  resumo: string;
51	  passos: PassoDaTrilha[];
52	}
53	
54	// As trilhas das famílias em que o aluno já obteve ao menos um item e que têm item da aba.
55	// A trilha mostra a família inteira, na ordem, com o próximo em cadeado (produto.md 4.4).
56	export function trilhasDaAba(
57	  premios: PremiosDoAluno,
58	  aba: AbaDeTrofeus,
59	): Trilha[] {
60	  return premios.familias
61	    .map((familia) => {
62	      const itens = premios.itens
63	        .filter((item) => item.familia === familia.codigo)
64	        .sort((a, b) => (a.ordemNaFamilia ?? 0) - (b.ordemNaFamilia ?? 0));
65	      return { familia, itens };
66	    })
67	    .filter(
68	      ({ itens }) =>
69	        itens.length >= 2 &&
70	        itens.some(obtido) &&
71	        itens.some((item) => ehDaAba(item, aba)),
72	    )
73	    .sort(
74	      (a, b) =>
75	        b.itens.filter(obtido).length - a.itens.filter(obtido).length ||
76	        a.familia.nome.localeCompare(b.familia.nome, "pt-BR"),
77	    )
78	    .map(({ familia, itens }) => {
79	      const proximo = itens.findIndex((item) => !obtido(item));
80	      return {
81	        codigo: familia.codigo,
82	        titulo: familia.nome,
83	        resumo: `${itens.filter(obtido).length} de ${itens.length} · ${formatarPontos(
84	          itens.reduce((soma, item) => soma + pontosObtidos(item), 0),
85	        )}`,
86	        passos: itens.map((item, indice) => ({
87	          id: item.codigo,
88	          // Como na prancheta, o passo diz o tier; o nome do item está na lista abaixo.
89	          rotulo: rotulosDeTier[item.tier as Tier],
90	          tier: item.tier as Tier,
91	          glifo: glifoDe(item),
92	          obtido: obtido(item),
93	          detalhes: obtido(item)
94	            ? [`+${formatarNumero(pontosObtidos(item))} pts`]
95	            : indice === proximo
96	              ? [`${formatarNumero(item.pontos)} pts`, "próximo"]
97	              : [`${formatarNumero(item.pontos)} pts`],
98	        })),
99	      };
100	    });
101	}
102	
103	export const glifoDe = (item: ItemDoAluno): "taca" | "fita" =>
104	  item.tipo === "medalha" ? "fita" : "taca";
105	
106	export const raridadeDe = (item: ItemDoAluno) =>
107	  item.raridade?.nivel as Raridade | undefined;
108	
109	export const pontosDaLinha = (item: ItemDoAluno) =>
110	  obtido(item)
111	    ? `+${formatarNumero(pontosObtidos(item))}`
112	    : formatarNumero(item.pontos);
113	
114	// Números no formato brasileiro: 15.020 (identidade-visual.md).
115	export const formatarNumero = (n: number) => n.toLocaleString("pt-BR");
116	
117	export const formatarPontos = (n: number) => `${formatarNumero(n)} pts`;
118	
119	// "12,5% dos alunos": o texto da raridade (produto.md 4.3).
120	export const textoDaRaridade = (percentual: number) =>
121	  `${percentual.toLocaleString("pt-BR", { maximumFractionDigits: 1 })}% dos alunos`;
122	
123	export type Instancia = NonNullable<
124	  ItemDoAluno["obtidos"][number]["instancia"]
125	>;
126	export type Progresso = NonNullable<ItemDoAluno["progresso"]>;
127	
128	// A instância de uma conquista obtida, em texto: "4º bimestre de 2026", "2026/2", "2026" ou
129	// "no curso" (passo 9). A API manda os números; o texto é do app.
130	export function rotuloDaInstancia(instancia: Instancia): string {
131	  const { periodo, ano, semestre, bimestre } = instancia;
132	  switch (periodo) {
133	    case "bimestre":
134	      return bimestre && ano ? `${bimestre}º bimestre de ${ano}` : "bimestre";
135	    case "semestre":
136	      return semestre && ano ? `${ano}/${semestre}` : "semestre";
137	    case "ano":
138	      return ano ? `${ano}` : "ano";
139	    default:
140	      return "no curso";
141	  }
142	}
143	
144	const NA_INSTANCIA_VIGENTE: Record<string, string> = {
145	  bimestre: "neste bimestre",
146	  semestre: "neste semestre",
147	  ano: "neste ano",
148	  curso: "no curso",
149	};
150	
151	// A linha de progresso da conquista que falta na instância vigente: "2 de 3 neste bimestre",
152	// ou "1 de 2 matérias neste bimestre" quando o alvo são as matérias do período. A API só a
153	// manda para o dono, fora do recesso e quando há alvo (passo 9).
154	export function textoDoProgresso(item: ItemDoAluno): string | null {
155	  const progresso = item.progresso;
156	  if (!progresso) {
157	    return null;
158	  }
159	
160	  const unidade = progresso.unidade === "materias" ? " matérias" : "";
161	  const onde = NA_INSTANCIA_VIGENTE[progresso.periodo] ?? "";
162	  return `${formatarNumero(progresso.contagem)} de ${formatarNumero(progresso.alvo)}${unidade} ${onde}`.trim();
163	}
164	
165	// Conquista é regra automática (prancheta trofeus-*.png): o critério, enquanto falta; obtida,
166	// a instância da mais recente e quantas vezes.
167	function detalheDaConquista(item: ItemDoAluno): string {
168	  const [maisRecente] = item.obtidos;
169	  if (!maisRecente) {
170	    return `Regra automática · ${item.criterio}`;
171	  }
172	
173	  const instancia = maisRecente.instancia
174	    ? ` · ${rotuloDaInstancia(maisRecente.instancia)}`
175	    : "";
176	  const vezes =
177	    item.obtidos.length > 1 ? ` · ${item.obtidos.length} vezes` : "";
178	  return `Regra automática${instancia}${vezes}`;
179	}
180	
181	// A linha de detalhe: o critério, ou, na medalha obtida, onde e quando veio a mais recente.
182	// Na conquista, a regra automática (detalheDaConquista).
183	export function detalheDaLinha(item: ItemDoAluno): string {
184	  if (item.tipo === "conquista") {
185	    return detalheDaConquista(item);
186	  }
187	
188	  const [maisRecente] = item.obtidos;
189	  if (!maisRecente || !maisRecente.materia) {
190	    return item.criterio;
191	  }
192	
193	  const vezes =
194	    item.obtidos.length > 1 ? ` · ${item.obtidos.length} vezes` : "";
195	  const bimestre = maisRecente.bimestre
196	    ? ` · ${maisRecente.bimestre}º bimestre`
197	    : "";
198	  return `${maisRecente.materia}${bimestre}${vezes}`;
199	}
